alter table  alberoproc_dyn2modellit add column FLAG_PUBBLICA numeric(1,0) NULL after FK_D2MT_ID,add column FLAG_TIPOFIRMA numeric(1,0) NULL after FLAG_PUBBLICA;
alter table  INVENTARIOPROCDYN2MODELLIT  add column FLAG_PUBBLICA numeric(1,0) NULL after FK_D2MT_ID,add column FLAG_TIPOFIRMA numeric(1,0) NULL after FLAG_PUBBLICA;
  
CREATE INDEX IDX_INVENTARIOPROCEDIMENTI_004 ON INVENTARIOPROCEDIMENTI(IDCOMUNE,CODICETIPO, CODICENATURA);

CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_DOCUMENTIISTANZA as SELECT 'DOCUMENTI' as TIPOLOGIA,
DOCUMENTIISTANZA.DOCUMENTO as DESCRIZIONE,
DOCUMENTIISTANZA.DATA,
DOCUMENTIISTANZA.CODICEOGGETTO,
DOCUMENTIISTANZA.STC_IDALLEGATO,
DOCUMENTIISTANZA.STC_IDDOCUMENTO,
DOCUMENTIISTANZA.CODICEISTANZA,
DOCUMENTIISTANZA.IDCOMUNE FROM  DOCUMENTIISTANZA UNION  SELECT 'MOVIMENTI' AS TIPOLOGIA,
 MOVIMENTIALLEGATI.DESCRIZIONE,
 MOVIMENTI.DATA,
 MOVIMENTIALLEGATI.CODICEOGGETTO,
 MOVIMENTIALLEGATI.STC_IDALLEGATO,
 MOVIMENTIALLEGATI.STC_IDDOCUMENTO,
 MOVIMENTI.CODICEISTANZA,
 MOVIMENTI.IDCOMUNE FROM MOVIMENTI,
 MOVIMENTIALLEGATI WHERE MOVIMENTIALLEGATI.IDCOMUNE = MOVIMENTI.IDCOMUNE AND MOVIMENTIALLEGATI.CODICEMOVIMENTO = MOVIMENTI.CODICEMOVIMENTO  UNION  SELECT 'ENDOPROCEDIMENTI' AS TIPOLOGIA,
 ISTANZEALLEGATI.ALLEGATOEXTRA AS DESCRIZIONE,
 ISTANZEPROCEDIMENTI.DATAATTIVAZIONE AS DATA,
 ISTANZEALLEGATI.CODICEOGGETTO,
 ISTANZEALLEGATI.STC_IDALLEGATO,
 ISTANZEALLEGATI.STC_IDDOCUMENTO,
 ISTANZEALLEGATI.CODICEISTANZA,
 ISTANZEALLEGATI.IDCOMUNE FROM INVENTARIOPROCEDIMENTI,
 ISTANZEALLEGATI,
 ISTANZEPROCEDIMENTI WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.IDCOMUNE = ISTANZEALLEGATI.IDCOMUNE AND ISTANZEPROCEDIMENTI.CODICEINVENTARIO = ISTANZEALLEGATI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.CODICEISTANZA = ISTANZEALLEGATI.CODICEISTANZA ;

alter table RESPONSABILI modify SCADENZARIOPREC numeric(2,0);

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_ISTANZECONCESSIONILISTA AS SELECT AUTORIZZAZIONI.IDCOMUNE,AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE,AUTORIZZAZIONI.DATA_CESSAZIONE AS DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE,AUTORIZZAZIONI.ID AS CONC_ID,AUTORIZZAZIONI.AUTORIZNUMERO AS CONC_NUMERO,AUTORIZZAZIONI.AUTORIZDATA AS CONC_DATARILASCIO,AUTORIZZAZIONI.AUTORIZDATA AS DATARILASCIO,AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA AS CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA,AUTORIZZAZIONI.FLAG_ATTIVA AS CONC_ATTIVA,AUTORIZZAZIONI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) AS CONC_TITOLARE,TITOLARE.CODICEFISCALE AS CONC_TIT_CF,TITOLARE.PARTITAIVA AS CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) AS IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) AS IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE,AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO,MERCATI.DESCRIZIONE AS CONC_MERCATO,MERCATI.ATTIVO AS MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO,MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO,MERCATI_USO.PESO AS PESO_MERCATO,MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.ID,AUTORIZZAZIONI LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUTORIZZAZIONI.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUTORIZZAZIONI.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID  LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI.IDCOMUNE=CAUS_STORICO.IDCOMUNE  AND AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE=CAUS_STORICO.CODICECAUSALE,MERCATI_D LEFT OUTER JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE=POSTEGGITIPOSPAZIO.IDCOMUNE AND MERCATI_D.FKCODICETIPOSPAZIO=POSTEGGITIPOSPAZIO.CODICE,ISTANZE LEFT OUTER JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE=IST_AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=IST_AZIENDA.CODICEANAGRAFE,CONCESSIONITIPI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_USO WHERE AUTORIZZAZIONI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO UNION SELECT AUTORIZZAZIONI_SUBENTRI.IDCOMUNE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE,AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE AS DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE,AUTORIZZAZIONI_SUBENTRI.ID AS CONC_ID,AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO AS CONC_NUMERO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS CONC_DATARILASCIO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS DATARILASCIO,AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA AS CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA,0 AS CONC_ATTIVA,AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) AS CONC_TITOLARE,TITOLARE.CODICEFISCALE AS CONC_TIT_CF,TITOLARE.PARTITAIVA AS CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) AS IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) AS IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO,MERCATI.DESCRIZIONE AS CONC_MERCATO,MERCATI.ATTIVO AS MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO,MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO,MERCATI_USO.PESO AS PESO_MERCATO,MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.ID,AUTORIZZAZIONI_SUBENTRI LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID  LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=CAUS_STORICO.IDCOMUNE,CONCESSIONITIPI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ISTANZE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_D,POSTEGGITIPOSPAZIO,MERCATI_USO,ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE;

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_CONCESSIONILISTA AS SELECT IDCOMUNE, SOFTWARE, CONC_ID, CONC_NUMERO, CONC_DATARILASCIO, CONC_DATASCADENZA, CONC_CODICETIPO, CONC_TIPO, CONC_STAGIONALEA, CONC_STAGIONALEDA, CONC_ATTIVA, CONC_CODICETITOLARE, CONC_TITOLARE, CONC_TIT_CF, CONC_TIT_PIVA, CONC_TIT_TIPOANAGRAFE, AUT_NUMERO, AUT_DATA, AUT_CODREGISTRO, AUT_REGISTRO, IST_CODICEISTANZA, IST_NUMEROISTANZA, IST_CODICERICHIEDENTE, IST_NOMINATIVO, IST_CODICEFISCALE, IST_PARTITAIVA, IST_RIC_TIPOANAGRAFE, ICONC_CODICECAUSALE, ICONC_CAUSALE, ICONC_CODICECAUSALESTORICO, ICONC_CAUSALESTORICO, CONC_IDMERCATO, CONC_MERCATO, MERC_ATTIVO, CONC_IDPOSTEGGIO, CONC_POSTEGGIO, CONC_POS_LARGHEZZA, CONC_POS_LUNGHEZZA, CONC_POS_SUPERFICIE, POST_IDTIPOSPAZIO, POST_TIPOSPAZIO, CONC_IDMERCATIUSO, CONC_DESCRIZIONEUSO, PESO_MERCATO, MERC_IDUSO, CONC_POS_CODICESTRADARIO FROM VW_ISTANZECONCESSIONILISTA;

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_I_ATTIVITACONCESSIONI AS SELECT I_ATTIVITA.ID AS I_IDATTIVITA, VW_CONCESSIONILISTA.IDCOMUNE, VW_CONCESSIONILISTA.SOFTWARE, VW_CONCESSIONILISTA.CONC_ID, VW_CONCESSIONILISTA.CONC_NUMERO, VW_CONCESSIONILISTA.CONC_DATARILASCIO, VW_CONCESSIONILISTA.CONC_DATASCADENZA, VW_CONCESSIONILISTA.CONC_CODICETIPO, VW_CONCESSIONILISTA.CONC_TIPO, VW_CONCESSIONILISTA.CONC_STAGIONALEA, VW_CONCESSIONILISTA.CONC_STAGIONALEDA, VW_CONCESSIONILISTA.CONC_ATTIVA, VW_CONCESSIONILISTA.CONC_CODICETITOLARE, VW_CONCESSIONILISTA.CONC_TITOLARE, VW_CONCESSIONILISTA.CONC_TIT_CF, VW_CONCESSIONILISTA.CONC_TIT_PIVA, VW_CONCESSIONILISTA.CONC_TIT_TIPOANAGRAFE, VW_CONCESSIONILISTA.AUT_NUMERO, VW_CONCESSIONILISTA.AUT_DATA, VW_CONCESSIONILISTA.AUT_CODREGISTRO, VW_CONCESSIONILISTA.AUT_REGISTRO, VW_CONCESSIONILISTA.IST_CODICEISTANZA, VW_CONCESSIONILISTA.IST_NUMEROISTANZA, VW_CONCESSIONILISTA.IST_CODICERICHIEDENTE, VW_CONCESSIONILISTA.IST_NOMINATIVO, VW_CONCESSIONILISTA.IST_CODICEFISCALE, VW_CONCESSIONILISTA.IST_PARTITAIVA, VW_CONCESSIONILISTA.IST_RIC_TIPOANAGRAFE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALE, VW_CONCESSIONILISTA.ICONC_CAUSALE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALESTORICO, VW_CONCESSIONILISTA.ICONC_CAUSALESTORICO, VW_CONCESSIONILISTA.CONC_IDMERCATO, VW_CONCESSIONILISTA.CONC_MERCATO, VW_CONCESSIONILISTA.MERC_ATTIVO, VW_CONCESSIONILISTA.CONC_IDPOSTEGGIO, VW_CONCESSIONILISTA.CONC_POSTEGGIO, VW_CONCESSIONILISTA.CONC_POS_LARGHEZZA, VW_CONCESSIONILISTA.CONC_POS_LUNGHEZZA, VW_CONCESSIONILISTA.CONC_POS_SUPERFICIE, VW_CONCESSIONILISTA.POST_IDTIPOSPAZIO, VW_CONCESSIONILISTA.POST_TIPOSPAZIO, VW_CONCESSIONILISTA.CONC_IDMERCATIUSO, VW_CONCESSIONILISTA.CONC_DESCRIZIONEUSO, VW_CONCESSIONILISTA.PESO_MERCATO, VW_CONCESSIONILISTA.MERC_IDUSO, VW_CONCESSIONILISTA.CONC_POS_CODICESTRADARIO FROM I_ATTIVITA,  VW_CONCESSIONILISTA,  ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID AND VW_CONCESSIONILISTA.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_CONCESSIONILISTA.IST_CODICEISTANZA = ISTANZE.CODICEISTANZA;